func maxTime(a, b time.Time) time.Time {
	if a.After(b) {
		return a
	}
	return b
}

type Generator interface {
	Execute(context.Context, string, Workload, []string, func(Sample) error) error
}
type Repository interface {
	SaveRun(context.Context, Run) error
	SaveResult(context.Context, string, int, Sample) error
	SaveUsage(context.Context, string, int, capacity.Usage) error
}
type Runner struct {
	Now        func() time.Time
	Generator  Generator
	Repository Repository
	Usage      func(context.Context, string, time.Time, time.Time) (capacity.Usage, error)
}

func (r Runner) Execute(ctx context.Context, region string, w Workload, clients []string, out io.Writer) (run Run, resultErr error) {
	if r.Now == nil {
		r.Now = time.Now
	}
	if err := w.Validate(); err != nil {
		return run, err
	}
	if region != "gru" && region != "sfo" || len(clients) == 0 || len(clients) > 3 || r.Generator == nil || r.Repository == nil || r.Usage == nil {
		return run, errors.New("benchmark requires region, clients, generator, SDK storage and usage")
	}
	for i, client := range clients {
		if !contains(languages, client) || contains(clients[:i], client) {
			return run, errors.New("clients must be distinct go,dotnet,rust")
		}
	}
	ctx, cancel := context.WithTimeout(ctx, MaxRun)
	defer cancel()
	levels := []int{w.Concurrency}
	if w.Name == "ramp" {
		levels = nil
		for n := 1; n < w.Concurrency; n *= 2 {
			levels = append(levels, n)
		}
		levels = append(levels, w.Concurrency)
		if w.Duration < 30*len(levels) || w.Duration+w.Warmup*len(levels) > workloadBudgetSeconds {
			return run, fmt.Errorf("ramp needs at least 30 measurement seconds per concurrency step and must fit warmups within %d seconds", workloadBudgetSeconds)
		}
	}
	run = Run{ID: entityid.New(), Region: region, Workload: w, Clients: clients, Started: r.Now().UTC(), Status: "running", Stages: []Stage{}}
	if err := r.Repository.SaveRun(ctx, run); err != nil {
		run.Status = "failed"
		run.Ended = r.Now().UTC()
		run.Verdict = capacityVerdict(w, nil, clients)
		return run, err
	}
	defer func() {
		run.Ended = r.Now().UTC()
		run.Status = "completed"
		if resultErr != nil {
			run.Status = "failed"
		}
		run.Verdict = capacityVerdict(w, run.Stages, clients)
		if resultErr != nil {
			run.Verdict.Qualified = false
			run.Verdict.Scale = "unknown"
		}
		finish, cancel := context.WithTimeout(context.WithoutCancel(ctx), time.Minute)
		defer cancel()
		if err := r.Repository.SaveRun(finish, run); err != nil {
			resultErr = errors.Join(resultErr, err)
			run.Status = "failed"
			run.Verdict.Qualified = false
			run.Verdict.Scale = "unknown"
		}
	}()
	for stageIndex, level := range levels {
		workload := w
		workload.Concurrency = level
		if w.Name == "ramp" {
			workload.Duration = w.Duration / len(levels)
			if stageIndex == 0 {
				workload.Duration += w.Duration % len(levels)
			}
		}
		stage := Stage{Concurrency: level, Duration: workload.Duration, From: r.Now().UTC(), Samples: []Sample{}, MeasurementFrom: map[string]time.Time{}}
		stageCtx, stop := context.WithCancel(ctx)
		pending := make(chan Sample, resultQueueSize)
		persistCtx, cancelPersistence := context.WithCancel(context.WithoutCancel(ctx))
		persisted := make(chan error, 1)
		go func(runID string) {
			err := r.persistResults(persistCtx, runID, stageIndex, pending, out)
			if err != nil {
				stop()
			}
			persisted <- err
		}(run.ID)
		seen := map[string]time.Time{}
		summaries := map[string]bool{}
		err := r.Generator.Execute(stageCtx, run.ID, workload, clients, func(sample Sample) error {
			if sample.Type == "measurement_start" {
				if !contains(clients, sample.Client) || sample.Region != region || !stage.MeasurementFrom[sample.Client].IsZero() || sample.TS.IsZero() || sample.TS.Before(stage.From.Add(time.Duration(w.Warmup)*time.Second-2*time.Second)) || sample.TS.After(r.Now().Add(time.Duration(w.Warmup)*time.Second+2*time.Second)) {
					return errors.New("invalid client measurement marker")
				}
				stage.MeasurementFrom[sample.Client] = sample.TS
				return nil
			}
			if err := sample.validate(sample.Client, region, w.Name, r.Now()); err != nil {
				return err
			}
			if !contains(clients, sample.Client) || summaries[sample.Client] || stage.MeasurementFrom[sample.Client].IsZero() {
				return errors.New("unexpected client, result after summary, or missing measurement marker")
			}
			if sample.Type == "summary" {
				if !summaryMatchesMix(sample, w) {
					return errors.New("summary operations must match workload mix")
				}
				summaries[sample.Client] = true
			} else {
				if sample.TS.Before(stage.MeasurementFrom[sample.Client].Add(-time.Duration(w.Warmup) * time.Second)) {
					return errors.New("sample predates its client measurement epoch")
				}
				if sample.TS.Before(stage.From.Add(-2 * time.Second)) {
					return errors.New("sample predates benchmark stage")
				}
				validOp := false
				for _, op := range w.Mix {
					if op.Op == sample.Op {
						validOp = true
					}
				}
				if !validOp {
					return errors.New("sample operation is outside workload mix")
				}
				key := sample.Client + "/" + sample.Op
				epoch := stage.MeasurementFrom[sample.Client].Add(-time.Duration(w.Warmup) * time.Second)
				if !seen[key].IsZero() && sample.TS.Sub(epoch)/time.Second <= seen[key].Sub(epoch)/time.Second {
					return errors.New("duplicate or out-of-order sample interval")
				}
				seen[key] = sample.TS
			}
			if len(stage.Samples) >= 20000 {
				return errors.New("benchmark result bound reached")
			}
			stage.Samples = append(stage.Samples, sample)
			if sample.Type == "" && (sample.Count > 0 && float64(sample.Errors)/float64(sample.Count) > 0.01 || sample.P99 > w.Targets.P99*2000) {
				stage.Stopped = "error rate >1% or p99 >2x target"
				stage.StoppedAt = r.Now().UTC()
				stop()
			}
			select {
			case pending <- sample:
				return nil
			default:
				stop()
				return errors.New("benchmark result queue overflow")
			}
		})
		stop()
		stage.To = r.Now().UTC()
		close(pending)
		drainCtx, drainCancel := context.WithTimeout(context.WithoutCancel(ctx), resultDrainTimeout)
		var persistenceErr error
		select {
		case persistenceErr = <-persisted:
		case <-drainCtx.Done():
			// ponytail: a blocked writer outlives this CLI run; require cancellable output before service reuse.
			persistenceErr = errResultDrainTimeout
		}
		drainCancel()
		cancelPersistence()
		usageCtx, usageCancel := context.WithTimeout(context.WithoutCancel(ctx), 30*time.Second)
		usageFrom, usageTo := measurementWindow(stage, clients)
		stage.Usage = capacity.Usage{Region: region}
		if usageFrom.Before(usageTo) {
			stage.Usage, resultErr = r.Usage(usageCtx, region, usageFrom, usageTo)
		}
		if resultErr == nil {
			resultErr = r.Repository.SaveUsage(usageCtx, run.ID, stageIndex, stage.Usage)
		}
		usageCancel()
		run.Stages = append(run.Stages, stage)
		if stage.Stopped != "" && err == context.Canceled {
			// Only a clean cancellation may complete a safety-stopped run.
			err = nil
		}
		if err != nil || persistenceErr != nil || resultErr != nil {
			return run, errors.Join(err, persistenceErr, resultErr)
		}
		if stage.Stopped != "" {
			return run, nil
		}
		if len(summaries) != len(clients) {
			return run, errors.New("client exited without its summary")
		}
	}
	return run, nil
}

func contains(values []string, value string) bool {
	for _, v := range values {
		if v == value {
			return true
		}
	}
	return false
}

func measurementWindow(stage Stage, clients []string) (from, to time.Time) {
	for _, client := range clients {
		start := stage.MeasurementFrom[client]
		if start.IsZero() {
			return time.Time{}, time.Time{}
		}
		if start.After(from) {
			from = start
		}
		end := start.Add(time.Duration(stage.Duration) * time.Second)
		if to.IsZero() || end.Before(to) {
			to = end
		}
	}
	if stage.To.Before(to) {
		to = stage.To
	}
	if !stage.StoppedAt.IsZero() && stage.StoppedAt.Before(to) {
		to = stage.StoppedAt
	}
	return from, to
}

const resultQueueSize = 256
const resultDrainTimeout = 30 * time.Second

var errResultDrainTimeout = errors.New("benchmark result drain timed out")
var errResultOutput = errors.New("stream benchmark result")

func (r Runner) persistResults(ctx context.Context, runID string, stage int, pending <-chan Sample, out io.Writer) error {
	encoder := json.NewEncoder(out)
	for sample := range pending {
		if err := ctx.Err(); err != nil {
			return err
		}
		saveCtx, cancel := context.WithTimeout(ctx, 30*time.Second)
		err := r.Repository.SaveResult(saveCtx, runID, stage, sample)
		cancel()
		if err != nil {
			return fmt.Errorf("save benchmark result: %w", err)
		}
		if err := ctx.Err(); err != nil {
			return err
		}
		if err := encoder.Encode(sample); err != nil {
			return fmt.Errorf("%w: %w", errResultOutput, err)
		}
	}
	return nil
}

func capacityVerdict(w Workload, stages []Stage, clients []string) Verdict {
	v := Verdict{P99TargetMS: w.Targets.P99, Bottleneck: "unknown", Scale: "unknown"}
	finalQualified := false
	finalEvidenceComplete := false
	finalSLOViolation := false
	for _, stage := range stages {
		duration := stage.Duration
		if duration == 0 {
			duration = w.Duration
		}
		evidenceComplete := true
		sloViolation := stage.Stopped != ""
		summaries := map[string]bool{}
		perOperation := map[string]map[int64]uint64{}
		successful := map[string]bool{}
		summaryRates := map[string]float64{}
		ops := 0.0
		for _, sample := range stage.Samples {
			if sample.Type == "summary" {
				summaries[sample.Client] = true
				summaryRates[sample.Client] = sample.OpsPerS
				if sample.ErrorRate > 0.01 {
					sloViolation = true
				}
				if !summaryMatchesMix(sample, w) {
					evidenceComplete = false
				}
				continue
			}
			start := stage.MeasurementFrom[sample.Client]
			if start.IsZero() {
				evidenceComplete = false
				continue
			}
			if sample.TS.Before(start) {
				continue
			}
			if !sample.TS.Before(start.Add(time.Duration(duration) * time.Second)) {
				evidenceComplete = false
				continue
			}
			if sample.Count > 0 && (sample.P99 > w.Targets.P99*1000 || float64(sample.Errors)/float64(sample.Count) > 0.01) {
				sloViolation = true
			}
			key := sample.Client + "/" + sample.Op
			seconds := perOperation[key]
			if seconds == nil {
				seconds = map[int64]uint64{}
				perOperation[key] = seconds
			}
			second := int64(sample.TS.Sub(start) / time.Second)
			if _, exists := seconds[second]; exists {
				evidenceComplete = false
				continue
			}
			seconds[second] = sample.Count
			if sample.Count > sample.Errors {
				successful[key] = true
			}
		}
		if len(summaries) != len(clients) {
			evidenceComplete = false
		}
		for _, client := range clients {
			var count uint64
			for _, op := range w.Mix {
				key := client + "/" + op.Op
				seconds := perOperation[key]
				if !successful[key] || len(seconds) < max(30, duration-2) {
					evidenceComplete = false
				}
				var times []int64
				for at := range seconds {
					times = append(times, at)
					count += seconds[at]
				}
				slices.Sort(times)
				for i := 1; i < len(times); i++ {
					if times[i]-times[i-1] > 2 {
						evidenceComplete = false
					}
				}
			}
			// Missing intervals still consume measurement time.
			observed := float64(count) / float64(duration)
			ops += observed
			if observed == 0 || summaryRates[client] < observed*0.95 || summaryRates[client] > observed*1.05 {
				evidenceComplete = false
			}
		}
		qualified := evidenceComplete && !sloViolation && stage.Usage.Complete
		if qualified && ops > v.MaxSustainedOps {
			v.MaxSustainedOps = ops
			v.Qualified = true
		}
		finalQualified = qualified
		finalEvidenceComplete = evidenceComplete
		finalSLOViolation = sloViolation
	}
	if len(stages) == 0 {
		return v
	}
	last := stages[len(stages)-1]
	if !last.Usage.Complete {
		v.Qualified = false
		return v
	}
	cpu, memory, cpuRatio, memoryRatio := 0.0, 0.0, 1.0, 1.0
	for _, node := range last.Usage.Nodes {
		if node.CPU.Headroom == nil || node.CPU.Limit == nil || node.Memory.Headroom == nil || node.Memory.Limit == nil {
			return v
		}
		cpu += node.CPU.Headroom.Min
		memory += node.Memory.Headroom.Min
		if node.CPU.Limit.Max > 0 {
			cpuRatio = min(cpuRatio, node.CPU.Headroom.Min/node.CPU.Limit.Max)
		}
		if node.Memory.Limit.Max > 0 {
			memoryRatio = min(memoryRatio, node.Memory.Headroom.Min/node.Memory.Limit.Max)
		}
	}
	// A service can hit its cgroup cap while its node still has spare capacity.
	for _, replica := range last.Usage.Replicas {
		if replica.CPU.Headroom == nil || replica.CPU.Limit == nil || replica.Memory.Headroom == nil || replica.Memory.Limit == nil {
			v.Qualified = false
			return v
		}
		if replica.CPU.Limit.Max > 0 {
			cpuRatio = min(cpuRatio, replica.CPU.Headroom.Min/replica.CPU.Limit.Max)
		}
		if replica.Memory.Limit.Max > 0 {
			memoryRatio = min(memoryRatio, replica.Memory.Headroom.Min/replica.Memory.Limit.Max)
		}
	}
	v.CPUHeadroom = &cpu
	v.MemoryHeadroom = &memory
	// A safety stop is measured pressure even though it truncates the evidence.
	if !finalEvidenceComplete && last.Stopped == "" {
		return v
	}
	v.Scale = "ok"
	switch {
	case cpuRatio < 0.2:
		v.Bottleneck = "cpu"
		v.Scale = "up"
	case memoryRatio < 0.2:
		v.Bottleneck = "memory"
		v.Scale = "up"
	case finalSLOViolation:
		v.Bottleneck = "latency/errors"
		v.Scale = "up"
	case finalQualified && cpuRatio > 0.6 && memoryRatio > 0.6:
		v.Bottleneck = "none"
		v.Scale = "down"
	default:
		v.Bottleneck = "none"
	}
	return v
}

func summaryMatchesMix(sample Sample, w Workload) bool {
	if len(sample.PerOp) != len(w.Mix) {
		return false
	}
	for _, op := range w.Mix {
		if _, ok := sample.PerOp[op.Op]; !ok {
			return false
		}
	}
	return true
}

func WriteVerdict(out io.Writer, run Run) error {
	_, err := fmt.Fprintf(out, "run %s: max sustained %.2f ops/s at p99 %.2f ms; qualified=%t; bottleneck=%s; scale=%s; temporary instance $%.6f\n", run.ID, run.Verdict.MaxSustainedOps, run.Verdict.P99TargetMS, run.Verdict.Qualified, run.Verdict.Bottleneck, run.Verdict.Scale, run.TemporaryInstanceUSD)
	if err != nil {
		return err
	}
	if run.Verdict.CPUHeadroom != nil && run.Verdict.MemoryHeadroom != nil {
		_, err = fmt.Fprintf(out, "headroom: %.2f CPU cores, %.2f MiB memory\n", *run.Verdict.CPUHeadroom, *run.Verdict.MemoryHeadroom/(1<<20))
	}
	return err
}

var namePattern = regexp.MustCompile(`^[a-z][a-z0-9-]{0,62}$`)
var imagePattern = regexp.MustCompile(`^[a-z0-9][a-z0-9./:_-]*@sha256:[a-f0-9]{64}$`)
var workerPathPattern = regexp.MustCompile(`^/[A-Za-z0-9_./-]+$`)
var languages = []string{"go", "dotnet", "rust"}
var operations = []string{"doc.create", "doc.get", "doc.update", "doc.delete", "query.simple", "query.indexed", "txn.multi"}

const MaxRun = 15 * time.Minute

const clientLifetime = MaxRun - time.Minute

// Keep a minute for client initialization, summary emission and database cleanup.
const workloadBudgetSeconds = int((clientLifetime - time.Minute) / time.Second)

type Workload struct {
	Name        string `json:"name"`
	Duration    int    `json:"duration_s"`
	Warmup      int    `json:"warmup_s"`
	Concurrency int    `json:"concurrency"`
	Dataset     struct {
		Documents int `json:"documents"`
		DocSize   int `json:"doc_size_bytes"`
	} `json:"dataset"`
	Mix []struct {
		Op      string  `json:"op"`
		Weight  float64 `json:"weight"`
		DocSize int     `json:"doc_size_bytes,omitempty"`
	} `json:"mix"`
	Targets struct {
		P99 float64 `json:"p99_ms"`
	} `json:"targets"`
}

func (w Workload) Validate() error {
	if !namePattern.MatchString(w.Name) || w.Duration < 30 || w.Duration > workloadBudgetSeconds || w.Warmup < 0 || w.Warmup > 300 || w.Duration+w.Warmup > workloadBudgetSeconds || w.Concurrency < 1 || w.Concurrency > 65536 || w.Dataset.Documents < 1 || w.Dataset.Documents > 10000000 || w.Dataset.DocSize < 1 || w.Dataset.DocSize > 4<<20 || !finite(w.Targets.P99) || w.Targets.P99 <= 0 || len(w.Mix) == 0 || len(w.Mix) > 7 {
		return fmt.Errorf("invalid workload or unbounded duration; duration must be 30..%d seconds and duration + warmup <= %d", workloadBudgetSeconds, workloadBudgetSeconds)
	}
	seen := map[string]bool{}
	for _, op := range w.Mix {
		if !slices.Contains(operations, op.Op) || seen[op.Op] || !finite(op.Weight) || op.Weight <= 0 || op.DocSize < 0 || op.DocSize > 4<<20 {
			return errors.New("invalid workload mix")
		}
		seen[op.Op] = true
	}
	return nil
}

type Sample struct {
	Type       string                     `json:"type,omitempty"`
	TS         time.Time                  `json:"ts,omitempty"`
	Client     string                     `json:"client"`
	SDK        string                     `json:"sdk,omitempty"`
	SDKVersion string                     `json:"sdk_version,omitempty"`
	Region     string                     `json:"region"`
	Op         string                     `json:"op,omitempty"`
	Count      uint64                     `json:"count,omitempty"`
	Errors     uint64                     `json:"errors,omitempty"`
	P50        float64                    `json:"p50_us,omitempty"`
	P95        float64                    `json:"p95_us,omitempty"`
	P99        float64                    `json:"p99_us,omitempty"`
	Max        float64                    `json:"max_us,omitempty"`
	Workload   string                     `json:"workload,omitempty"`
	OpsPerS    float64                    `json:"ops_per_s,omitempty"`
	ErrorRate  float64                    `json:"error_rate,omitempty"`
	PerOp      map[string]json.RawMessage `json:"per_op,omitempty"`
}

// Presence is checked at both JSONL boundaries before zero values can qualify.
func (s *Sample) UnmarshalJSON(data []byte) error {
	type wireSample Sample
	var value wireSample
	if err := json.Unmarshal(data, &value); err != nil {
		return err
	}
	var fields map[string]json.RawMessage
	if err := json.Unmarshal(data, &fields); err != nil {
		return err
	}
	required := []string{"ts", "client", "sdk", "sdk_version", "region", "op", "count", "errors", "p50_us", "p95_us", "p99_us", "max_us"}
	if value.Type == "summary" {
		required = []string{"type", "client", "region", "workload", "ops_per_s", "error_rate", "per_op"}
	}
	for _, key := range required {
		if len(fields[key]) == 0 || bytes.Equal(bytes.TrimSpace(fields[key]), []byte("null")) {
			return fmt.Errorf("benchmark JSONL requires non-null %s", key)
		}
	}
	*s = Sample(value)
	return nil
}

func (s Sample) Validate(client, region, workload string) error {
	return s.validate(client, region, workload, time.Now())
}
func (s Sample) validate(client, region, workload string, now time.Time) error {
	if s.Client != client || s.Region != region {
		return errors.New("client result identity mismatch")
	}
	if s.Type == "summary" {
		if s.Workload != workload || !finite(s.OpsPerS) || s.OpsPerS < 0 || !finite(s.ErrorRate) || s.ErrorRate < 0 || s.ErrorRate > 1 || len(s.PerOp) == 0 || len(s.PerOp) > len(operations) {
			return errors.New("invalid client summary")
		}
		for op, data := range s.PerOp {
			if !slices.Contains(operations, op) || len(data) > 64<<10 || len(data) == 0 || data[0] != '{' {
				return errors.New("invalid per-operation summary")
			}
		}
		return nil
	}
	if s.Type != "" || s.TS.IsZero() || s.TS.After(now.Add(2*time.Second)) || s.TS.Before(now.Add(-MaxRun-time.Minute)) || !slices.Contains(operations, s.Op) || s.SDK == "" || len(s.SDK) > 64 || s.SDKVersion == "" || len(s.SDKVersion) > 128 || s.Errors > s.Count || len(s.PerOp) > 0 {
		return errors.New("invalid per-second client sample")
	}
	if !finite(s.P50) || !finite(s.P95) || !finite(s.P99) || !finite(s.Max) || s.P50 < 0 || s.P50 > s.P95 || s.P95 > s.P99 || s.P99 > s.Max {
		return errors.New("invalid latency percentiles")
	}
	return nil
}

// Required per-second fields stay present when their value is zero.
func (s Sample) MarshalJSON() ([]byte, error) {
	if s.Type == "summary" {
		return json.Marshal(struct {
			Type     string                     `json:"type"`
			Client   string                     `json:"client"`
			Region   string                     `json:"region"`
			Workload string                     `json:"workload"`
			Ops      float64                    `json:"ops_per_s"`
			Errors   float64                    `json:"error_rate"`
			PerOp    map[string]json.RawMessage `json:"per_op"`
		}{s.Type, s.Client, s.Region, s.Workload, s.OpsPerS, s.ErrorRate, s.PerOp})
	}
	return json.Marshal(struct {
		TS      time.Time `json:"ts"`
		Client  string    `json:"client"`
		SDK     string    `json:"sdk"`
		Version string    `json:"sdk_version"`
		Region  string    `json:"region"`
		Op      string    `json:"op"`
		Count   uint64    `json:"count"`
		Errors  uint64    `json:"errors"`
		P50     float64   `json:"p50_us"`
		P95     float64   `json:"p95_us"`
		P99     float64   `json:"p99_us"`
		Max     float64   `json:"max_us"`
	}{s.TS, s.Client, s.SDK, s.SDKVersion, s.Region, s.Op, s.Count, s.Errors, s.P50, s.P95, s.P99, s.Max})
}

func finite(value float64) bool { return !math.IsNaN(value) && !math.IsInf(value, 0) }

func finishRun(reports string, out io.Writer, run Run, runErr error) error {
	if run.ID == "" {
		return runErr
	}
	path, reportErr := writeReport(reports, run)
	runErr = errors.Join(runErr, reportErr)
	if errors.Is(runErr, errResultDrainTimeout) || errors.Is(runErr, errResultOutput) {
		return runErr
	}
	runErr = errors.Join(runErr, WriteVerdict(out, run))
	if reportErr == nil {
		_, err := fmt.Fprintln(out, path)
		runErr = errors.Join(runErr, err)
	}
	return runErr
}

func writeReport(root string, run Run) (string, error) {
	dir := filepath.Join(root, run.Region)
	if err := os.MkdirAll(dir, 0755); err != nil {
		return "", err
	}
	path := filepath.Join(dir, run.Started.UTC().Format("2006-01-02")+"-"+run.Workload.Name+".md")
	f, err := os.OpenFile(path, os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0644)
	if err != nil {
		return "", err
	}
	err = func() error {
		if _, err := fmt.Fprintf(f, "# %s / %s\n\n", run.Region, run.Workload.Name); err != nil {
			return err
		}
		if err := WriteVerdict(f, run); err != nil {
			return err
		}
		if _, err := fmt.Fprintln(f, "\n```json"); err != nil {
			return err
		}
		if err := json.NewEncoder(f).Encode(run); err != nil {
			return err
		}
		_, err := io.WriteString(f, "```\n\n")
		return err
	}()
	return path, errors.Join(err, f.Close())
}

func installHelper(t *testing.T, name, test string) {
	t.Helper()
	dir := t.TempDir()
	exe, err := os.Executable()
	if err != nil {
		t.Fatal(err)
	}
	script := "#!/bin/sh\nexec '" + strings.ReplaceAll(exe, "'", "'\\''") + "' -test.run=^" + test + "$ -- \"$@\"\n"
	if err := os.WriteFile(filepath.Join(dir, name), []byte(script), 0755); err != nil {
		t.Fatal(err)
	}
	t.Setenv("PATH", dir+string(os.PathListSeparator)+os.Getenv("PATH"))
	t.Setenv("GORACE", "atexit_sleep_ms=0")
}

func TestPodmanHelper(t *testing.T) {
	state := os.Getenv("TS_761_PODMAN_STATE")
	if state == "" {
		return
	}
	var args []string
	for i, arg := range os.Args {
		if arg == "--" {
			args = os.Args[i+1:]
			break
		}
	}
	if len(args) == 0 {
		os.Exit(2)
	}
	name := args[len(args)-1]
	switch args[0] {
	case "run":
		label := ""
		for i, arg := range args {
			if arg == "--name" {
				name = args[i+1]
			}
			if arg == "--label" {
				label = strings.TrimPrefix(args[i+1], "ts-bench-job=")
			}
		}
		f, err := os.Open("/proc/self/fd/3")
		if err != nil {
			os.Exit(2)
		}
		env, err := io.ReadAll(f)
		f.Close()
		if err != nil || !bytes.Contains(env, []byte("TS_BENCH_CLIENT_SECRET=private-test-value")) {
			os.Exit(2)
		}
		if err := os.WriteFile(filepath.Join(state, name), []byte(label), 0600); err != nil {
			os.Exit(2)
		}
		switch os.Getenv("TS_761_PODMAN_MODE") {
		case "warmup":
			var w Workload
			if json.NewDecoder(os.Stdin).Decode(&w) != nil {
				os.Exit(2)
			}
			client, delay := "go", 10
			if strings.HasSuffix(name, "-rust") {
				client, delay = "rust", 6
			}
			at := time.Now().UTC().Add(-time.Duration(w.Warmup+w.Duration+delay) * time.Second)
			encoder := json.NewEncoder(os.Stdout)
			for second := range w.Warmup + w.Duration {
				count, p99 := uint64(100), 100.0
				if second < w.Warmup {
					count, p99 = 10, w.Targets.P99*1500
				}
				_ = encoder.Encode(Sample{TS: at.Add(time.Duration(second) * time.Second), Client: client, SDK: client, SDKVersion: "test", Region: "gru", Op: "doc.get", Count: count, P50: 10, P95: 30, P99: p99, Max: p99})
			}
			_ = encoder.Encode(Sample{Type: "summary", Client: client, Region: "gru", Workload: w.Name, OpsPerS: 100, PerOp: map[string]json.RawMessage{"doc.get": json.RawMessage(`{}`)}})
			os.Exit(0)
		case "oversized":
			_, _ = io.WriteString(os.Stdout, strings.Repeat("x", 1<<20))
			for {
				time.Sleep(time.Minute)
			}
		case "stream":
			_ = json.NewEncoder(os.Stdout).Encode(Sample{TS: time.Now().UTC(), Client: "go", SDK: "go", SDKVersion: "test", Region: "gru", Op: "doc.get", Count: 100, P99: 30, Max: 40})
			for {
				time.Sleep(time.Minute)
			}
		case "missing-fields":
			_ = json.NewEncoder(os.Stdout).Encode(map[string]any{"ts": time.Now().UTC(), "client": "go", "sdk": "go", "sdk_version": "test", "region": "gru", "op": "doc.get", "count": 100, "errors": 0})
			for {
				time.Sleep(time.Minute)
			}
		}
		fmt.Println("invalid-result")
		os.Exit(0)
	case "inspect":
		data, err := os.ReadFile(filepath.Join(state, name))
		if err != nil {
			os.Exit(1)
		}
		fmt.Println(string(data))
		os.Exit(0)
	case "container":
		if _, err := os.Stat(filepath.Join(state, name)); err != nil {
			os.Exit(1)
		}
		os.Exit(0)
	case "stop":
		switch os.Getenv("TS_761_PODMAN_MODE") {
		case "cleanup-barrier":
			_ = os.WriteFile(filepath.Join(state, ".stopped-"+name), nil, 0600)
			deadline := time.Now().Add(3 * time.Second)
			for {
				stopped, _ := filepath.Glob(filepath.Join(state, ".stopped-*"))
				if len(stopped) == 3 {
					break
				}
				if time.Now().After(deadline) {
					os.Exit(1)
				}
				time.Sleep(10 * time.Millisecond)
			}
		case "cleanup-failures":
			os.Exit(1)
		}
		os.Exit(0)
	case "rm":
		if os.Getenv("TS_761_PODMAN_MODE") == "cleanup-failures" && strings.HasSuffix(name, "-go") {
			os.Exit(1)
		}
		_ = os.Remove(filepath.Join(state, name))
		os.Exit(0)
	default:
		os.Exit(2)
	}
}

func runContainers(ctx context.Context, job Job, secrets map[string]string, out io.Writer) (resultErr error) {
	ctx, cancel := context.WithCancel(ctx)
	defer cancel()
	names := make([]string, 0, len(job.Clients))
	for _, client := range job.Clients {
		names = append(names, "bench-"+job.ID+"-"+client)
	}
	defer func() {
		resultErr = errors.Join(resultErr, cleanupContainers(ctx, job.ID, names))
	}()
	var mu sync.Mutex
	var wg sync.WaitGroup
	var runErr error
	workload, _ := json.Marshal(job.Workload)
	for i, client := range job.Clients {
		wg.Add(1)
		go func(client, name string) {
			defer wg.Done()
			started := false
			err := container(ctx, job, client, name, workload, secrets, func(line []byte) error {
				var sample Sample
				if json.Unmarshal(line, &sample) != nil {
					return errors.New("client returned malformed JSONL")
				}
				if err := sample.Validate(client, job.Region, job.Workload.Name); err != nil {
					return err
				}
				mu.Lock()
				defer mu.Unlock()
				if !started && sample.Type == "" {
					// The first client interval anchors warmup independently of job startup.
					if err := json.NewEncoder(out).Encode(workerControl{Type: "measurement_start", JobID: job.ID, Client: client, MeasurementFrom: sample.TS.Add(time.Duration(job.Workload.Warmup) * time.Second)}); err != nil {
						return err
					}
					started = true
				}
				_, err := out.Write(append(line, '\n'))
				return err
			})
			if err != nil {
				mu.Lock()
				runErr = errors.Join(runErr, err)
				mu.Unlock()
				cancel()
			}
		}(client, names[i])
	}
	wg.Wait()
	return runErr
}

func cleanupContainers(ctx context.Context, jobID string, names []string) (resultErr error) {
	cleanup, stop := context.WithTimeout(context.WithoutCancel(ctx), 90*time.Second)
	defer stop()
	var wg sync.WaitGroup
	cleanupErrors := make([]error, len(names))
	// Each client gets its grace period without consuming another client's.
	for i, name := range names {
		wg.Add(1)
		go func() {
			defer wg.Done()
			cleanupErrors[i] = cleanupContainer(cleanup, jobID, name)
		}()
	}
	wg.Wait()
	resultErr = errors.Join(cleanupErrors...)
	if resultErr != nil {
		return &containerCleanupError{resultErr}
	}
	return nil
}

func cleanupContainer(ctx context.Context, jobID, name string) (resultErr error) {
	// Names are newly generated ULIDs; never replace a pre-existing container.
	inspect := exec.CommandContext(ctx, "podman", "inspect", "--format", "{{ index .Config.Labels \"ts-bench-job\" }}", name)
	data, err := inspect.Output()
	if err != nil {
		check := exec.CommandContext(ctx, "podman", "container", "exists", name).Run()
		var exit *exec.ExitError
		if !errors.As(check, &exit) || exit.ExitCode() != 1 {
			return errors.New("cannot verify benchmark container cleanup")
		}
		return nil
	}
	if strings.TrimSpace(string(data)) != jobID {
		return errors.New("refused cleanup of a foreign container")
	}
	if exec.CommandContext(ctx, "podman", "stop", "--ignore", "--time", "30", name).Run() != nil {
		resultErr = errors.New("benchmark container stop failed")
	}
	if exec.CommandContext(ctx, "podman", "rm", "--force", "--ignore", name).Run() != nil {
		resultErr = errors.Join(resultErr, errors.New("benchmark container cleanup failed"))
	}
	return resultErr
}

func container(ctx context.Context, job Job, client, name string, workload []byte, secrets map[string]string, emit func([]byte) error) error {
	reader, writer, err := os.Pipe()
	if err != nil {
		return err
	}
	defer reader.Close()
	// Secrets cross an inherited pipe, never argv, logs, a disk file or stdin.
	env := fmt.Sprintf("TS_BENCH_CLIENT_ID=%s\nTS_BENCH_CLIENT_SECRET=%s\nTS_BENCH_RUN_ID=%s\n", secrets["TS_BENCH_CLIENT_ID"], secrets["TS_BENCH_CLIENT_SECRET"], entityid.New())
	go func() { _, _ = io.WriteString(writer, env); _ = writer.Close() }()
	command := exec.CommandContext(ctx, "podman", "run", "--rm", "--pull=never", "--name", name, "--label", "ts-bench-job="+job.ID, "--read-only", "--cap-drop=ALL", "--security-opt=no-new-privileges", "--pids-limit=256", "--cpus=1", "--memory=1g", "--tmpfs", "/tmp:rw,size=256m", "--stop-signal=SIGINT", "--stop-timeout=30", fmt.Sprintf("--timeout=%d", int(clientLifetime/time.Second)), "--env-file=/proc/self/fd/3", "-i", job.Images[client], "run", "--workload", "/dev/stdin", "--region", job.Region, "--out", "/dev/stdout")
	command.ExtraFiles = []*os.File{reader}
	command.Stdin = bytes.NewReader(workload)
	command.Stderr = io.Discard
	stdout, err := command.StdoutPipe()
	if err != nil {
		return err
	}
	if err := command.Start(); err != nil {
		return errors.New("client container could not start")
	}
	scanner := bufio.NewScanner(stdout)
	scanner.Buffer(make([]byte, 4096), 256<<10)
	var emitErr error
	for scanner.Scan() {
		if err := emit(bytes.Clone(scanner.Bytes())); err != nil {
			emitErr = err
			_ = command.Process.Kill()
			break
		}
	}
	if scanErr := scanner.Err(); scanErr != nil {
		emitErr = errors.Join(emitErr, fmt.Errorf("client JSONL exceeded limits: %w", scanErr))
		_ = command.Process.Kill()
	}
	err = command.Wait()
	if emitErr != nil {
		return emitErr
	}
	if err != nil {
		if ctx.Err() != nil {
			return ctx.Err()
		}
		return errors.New("benchmark client container failed")
	}
	return nil
}
